    ($SATQ$869a32f1$SATQ$, NULL, NULL, $SATQ$08099-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.C.$SATQ$, $SATQ$One-variable data: Distributions and measures of center and spread$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<div class="stimulus_reference " xmlns="http://www.imsglobal.org/xsd/apip/apipv1p0/qtiitem/imsqti_v2p1">
	<div class="passage ">
		<div class="prose style:1 ">
			<p class="passage_para ">The high temperature, in degrees Fahrenheit (&deg;F), in a certain city was recorded for each of 5&nbsp;days. The data are shown below.</p>

			<div class="table_wrapper ">
				<table class="tcp-8389d6ef-0903-4b89-9a9e-79d06cf1bfb0">
					<tbody>
						<tr>
							<td>
								<table class="table_WithBorder tcp-58153dcb-3058-4559-9f1e-ecc2f3a03d92">
									<tbody class="tbody ">
										<tr class="row ">
											<td class="entry align:left colname:col1 ">Day</td>
											<td class="entry align:center colname:col2  tcp-548f0de6-4421-414e-ad62-3ee1d67e7e3e">1</td>
											<td class="entry align:center colname:col3  tcp-9e683c8d-1faf-4b39-8f0f-36f87dc55060">2</td>
											<td class="entry align:center colname:col4  tcp-c888bde5-88b2-4701-9c87-0f73d899b51d">3</td>
											<td class="entry align:center colname:col5  tcp-67515d51-71f5-4013-a647-2c3e4564a18b">4</td>
											<td class="entry align:center colname:col6  tcp-37879877-f5ad-4608-a605-bdc31f26c468">5</td>
										</tr>
										<tr class="row ">
											<td class="entry colname:col1 ">High temperature (&deg;F)</td>
											<td class="entry align:center colname:col2 ">81</td>
											<td class="entry align:center colname:col3 ">80</td>
											<td class="entry align:center colname:col4 ">81</td>
											<td class="entry align:center colname:col5 ">81</td>
											<td class="entry align:center colname:col6 ">82</td>
										</tr>
									</tbody>
								</table>
							</td>
						</tr>
					</tbody>
				</table>
			</div>
		</div>
	</div>
