7c.png\" alt=\"k plus 3\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_005_c12c1c8a.png\" alt=\"k plus 4\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_006_aa3805f1.png\" alt=\"k plus 5\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_007_0c54b858.png\" alt=\"k plus 6\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_008_c2d676ed.png\" alt=\"k plus 7\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_009_e77d0525.png\" alt=\"k plus 8\"></span>. The mean of the integers is their sum divided by 9: <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_010_da40cf2f.png\" alt=\"the fraction with numerator open parenthesis, k plus, k plus 1, plus, k plus 2, plus, dot dot dot, plus, k plus 8, close parenthesis, and denominator 9, equals, the fraction with numerator, open parenthesis, 9 k plus 36, close parenthesis, and denominator 9\"></span>, which simplifies to <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_011_c12c1c8a.png\" alt=\"k plus 4\"></span>. So <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_012_dc19ba30.png\" alt=\"a, equals, k plus 4\"></span>. Since there is an odd number of integers (nine), the median is the integer in the middle when all the integers are ordered from least to greatest: <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_013_c12c1c8a.png\" alt=\"k plus 4\"></span>. So <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_014_c02223ed.png\" alt=\"b equals, k plus 4\"></span>. Therefore, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"https://bkmyfcolrdumyrwktjrr.supabase.co/storage/v1/object/public/sat-images/881ef5f5/img_015_5fc09830.png\" alt=\"the absolute value of a, minus b, end absolute value, equals, the absolute value of, open parenthesis, k plus 4, close parenthesis, minus, open parenthesis, k plus 4, close parenthesis, end absolute value\"></span>, which is 0.</p>\n","answer_style":"SPR","section":"Math","image_count":16,"raw_list":{"updateDate":1691007959622,"pPcc":"SAT#Q","questionId":"881ef5f5","skill_cd":"Q.C.","score_band_range_cd":5,"skill_desc":"One-variable data: Distributions and measures of center and spread","createDate":1691007959622,"program":"SAT","primary_class_cd_desc":"Problem-Solving and Data Analysis","ibn":"028792-DC","external_id":null,"primary_class_cd":"Q","uId":"a73a938a-d5cc-4213-aabe-43e9f19bf06c","difficulty":"M"},"raw_detail":{"item_id":"028792-DC","section":"Math","prompt":"<p class=\"stem_paragraph \">If <span class=\"italic\">a</span> is the mean and <span class=\"italic\">b</span> is the median of nine consecutive integers, what is the value of <span class=\"math_expression \"><span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"the absolute value of, a, minus b, end absolute value\"></span></span> ?</p>\n","answer":{"style":"SPR","rationale":"<p>The correct answer is 0. Any nine consecutive integers can be written as <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 1\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 2\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 3\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 4\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 5\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 6\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 7\"></span>, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 8\"></span>. The mean of the integers is their sum divided by 9: <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"the fraction with numerator open parenthesis, k plus, k plus 1, plus, k plus 2, plus, dot dot dot, plus, k plus 8, close parenthesis, and denominator 9, equals, the fraction with numerator, open parenthesis, 9 k plus 36, close parenthesis, and denominator 9\"></span>, which simplifies to <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 4\"></span>. So <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"a, equals, k plus 4\"></span>. Since there is an odd number of integers (nine), the median is the integer in the middle when all the integers are ordered from least to greatest: <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"k plus 4\"></span>. So <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"b equals, k plus 4\"></span>. Therefore, <span class=\"math-container\"><img align=\"middle\" role=\"math\" class=\"math-img\" src=\"data:image/png;base64,\" alt=\"the absolute value of a, minus b, end absolute value, equals, the absolute value of, open parenthesis, k plus 4, close parenthesis, minus, open parenthesis, k plus 4, close parenthesis, end absolute value\"></span>, which is 0.</p>\n"}},"createDate":1691007959622,"updateDate":1691007959622,"correct_answer_extracted_from_rationale":true}$SATQ$::jsonb, 1691007959622, 1691007959622),
